mapper.select:
SELECT taer.`tech_ach_evaluation_report_id`, taer.`publish_time`, taer.`application_status`,
taer.`evaluation_status`, ta.`technology_achievement_id` AS tech_ach_id, ta.`title`, ta.`category` FROM
tech_ach_evaluation_report AS taer
INNER JOIN technology_achievement AS ta
ON taer.`technology_achievement_id` = ta.`technology_achievement_id`


        AND TO_DAYS(NOW()) - TO_DAYS(taer.`publish_time`) <= #{duration}


        AND taer.`application_status` = #{applicationStatus}


        AND taer.`evaluation_status` = #{evaluationStatus}


ORDER BY taer.`publish_time` DESC
